import sys

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    a = [int(x) for x in data[1:1 + n]]
    cand = []
    for i in range(n):
        if not cand or a[i] < a[cand[-1]]:
            cand.append(i)
    ans = 0
    for j in range(n - 1, -1, -1):
        while cand and a[j] > a[cand[-1]]:
            ans = max(ans, j - cand.pop())
        if not cand:
            break
    print(ans)

